with filtered as (select *, cast(status_bits as string) as status_bits_num, floor(humidity) as humidity_whole from device_readings where reading_ts >= timestamp '2025-09-01 09:00:00') select device_code, (unix_timestamp(max(reading_ts)) - unix_timestamp(min(reading_ts))) / 60 as duration_min, percentile_approx(status_bits, 0.9) as status_bits_p90, sum(humidity) filter (where device_code = 'DV-02') as dv_02_total_humidity, stddev_samp(humidity) as humidity_stddev from filtered group by 1 having sum(humidity) filter (where device_code = 'DV-02') > 0 order by dv_02_total_humidity desc;
